#include "ForestTypes.h"
#include "Engine/StaticMesh.h"
#include "Materials/MaterialInterface.h"

namespace
{
	/** Greybox assets generated by Scripts/build_greybox.py: real-world size, logs along X, pivot at the centre. */
	UStaticMesh* LoadGreybox(const TCHAR* Name)
	{
		return LoadObject<UStaticMesh>(nullptr, *FString::Printf(TEXT("/Game/Greybox/Meshes/%s.%s"), Name, Name));
	}
}

const TArray<EForestItem>& ForestItems::GetAllItems()
{
	static const TArray<EForestItem> Items = {
		EForestItem::TrunkLog, EForestItem::BigLog, EForestItem::Log,
		EForestItem::HalfLog, EForestItem::ShortLog, EForestItem::HollowLog, EForestItem::Plank,
		EForestItem::Beam, EForestItem::Firewood, EForestItem::Stone, EForestItem::StoneBlock,
		EForestItem::WindowBuck, EForestItem::DoorBuck };
	return Items;
}

FString ForestItems::GetDisplayName(EForestItem Item)
{
	switch (Item)
	{
	case EForestItem::Log:        return TEXT("Kütük");
	case EForestItem::TrunkLog:   return TEXT("G\u00F6vde");
	case EForestItem::BigLog:     return TEXT("B\u00FCy\u00FCk K\u00FCt\u00FCk");
	case EForestItem::HalfLog:    return TEXT("Yar\u0131m K\u00FCt\u00FCk");
	case EForestItem::ShortLog:   return TEXT("K\u0131sa K\u00FCt\u00FCk");
	case EForestItem::HollowLog:  return TEXT("Oyuk K\u00FCt\u00FCk");
	case EForestItem::Plank:      return TEXT("Kalas");
	case EForestItem::Beam:       return TEXT("Kiriş");
	case EForestItem::Firewood:   return TEXT("Odun");
	case EForestItem::Stone:      return TEXT("Taş");
	case EForestItem::StoneBlock: return TEXT("Taş Blok");
	case EForestItem::WindowBuck: return TEXT("Pencere Kasası");
	case EForestItem::DoorBuck:   return TEXT("Kapı Kasası");
	default:                      return TEXT("");
	}
}

bool ForestItems::IsCarriedItem(EForestItem Item)
{
	return IsLogItem(Item);
}

bool ForestItems::IsLogItem(EForestItem Item)
{
	return Item == EForestItem::Log || Item == EForestItem::BigLog || Item == EForestItem::TrunkLog;
}

UStaticMesh* ForestItems::GetMesh(EForestItem Item, int32 Variant)
{
	switch (Item)
	{
	case EForestItem::TrunkLog:   return GetLogStageMesh(1);
	case EForestItem::BigLog:     return GetLogStageMesh(2);
	case EForestItem::Log:        return LoadGreybox(TEXT("SM_GB_Log"));
	case EForestItem::HalfLog:    return LoadGreybox(TEXT("SM_GB_LogHalf"));
	case EForestItem::ShortLog:   return LoadGreybox(TEXT("SM_GB_LogShort"));
	case EForestItem::HollowLog:  return LoadGreybox(TEXT("SM_GB_LogHollow"));
	case EForestItem::Plank:      return LoadGreybox(TEXT("SM_GB_Plank"));
	case EForestItem::Beam:       return LoadGreybox(TEXT("SM_GB_Beam"));
	case EForestItem::Firewood:   return LoadGreybox(TEXT("SM_GB_Firewood"));
	case EForestItem::Stone:      return LoadGreybox(TEXT("SM_GB_Stone"));
	case EForestItem::StoneBlock: return LoadGreybox(TEXT("SM_GB_StoneBlock"));
	// A 100 x 100 cm frame, stood on its bottom edge and scaled to the opening.
	case EForestItem::WindowBuck:
	case EForestItem::DoorBuck:   return LoadGreybox(TEXT("SM_GB_Frame"));
	default:                      return nullptr;
	}
}

FVector ForestItems::GetItemScale(EForestItem Item)
{
	switch (Item)
	{
	// Greybox pieces are modelled at their real size; only the frame and the big log stages are scaled.
	case EForestItem::WindowBuck: return FVector(1.0f, 0.4f, 1.2f);
	case EForestItem::DoorBuck:   return FVector(1.0f, 0.4f, 2.1f);
	case EForestItem::TrunkLog:   return GetLogStageScale(1);
	case EForestItem::BigLog:     return GetLogStageScale(2);
	default:                      return FVector::OneVector;
	}
}

UStaticMesh* ForestItems::GetLogStageMesh(int32 Stage)
{
	// Every stage is the same greybox log, stretched by GetLogStageScale.
	return GetMesh(EForestItem::Log);
}

FVector ForestItems::GetLogStageScale(int32 Stage)
{
	if (Stage >= 3)
	{
		return GetItemScale(EForestItem::Log);
	}
	const UStaticMesh* Final = GetMesh(EForestItem::Log);
	const UStaticMesh* Mesh = GetLogStageMesh(Stage);
	if (!Final || !Mesh)
	{
		return FVector::OneVector;
	}
	const float FinalLength = Final->GetBoundingBox().GetSize().X * GetItemScale(EForestItem::Log).X;
	const float Length = FinalLength * (Stage == 1 ? 4.f : 2.f);
	const float Thickness = Stage == 1 ? 95.f : 80.f;
	const FVector Size = Mesh->GetBoundingBox().GetSize();
	const float Across = Thickness / ((Size.Y + Size.Z) * 0.5f);
	return FVector(Length / Size.X, Across, Across);
}

UStaticMesh* ForestItems::GetDebrisMesh(EHarvestType Type, int32 Variant)
{
	return LoadGreybox(Type == EHarvestType::Rock ? TEXT("SM_GB_Stone") : TEXT("SM_GB_Chip"));
}

UStaticMesh* ForestItems::GetToolMesh(EForestTool Tool)
{
	// Tool meshes stand along Z: grip near the bottom, head on top, blade or face toward +X.
	switch (Tool)
	{
	case EForestTool::Pickaxe: return LoadGreybox(TEXT("SM_GB_Tool_Pickaxe"));
	case EForestTool::Trowel:  return LoadGreybox(TEXT("SM_GB_Tool_Trowel"));
	default:                   return LoadGreybox(TEXT("SM_GB_Tool_Axe"));
	}
}

UMaterialInterface* ForestItems::GetHitMarkMaterial(EHarvestType Type)
{
	return LoadObject<UMaterialInterface>(nullptr, Type == EHarvestType::Rock
		? TEXT("/Game/Gameplay/Materials/MI_HitMark_Rock.MI_HitMark_Rock")
		: TEXT("/Game/Gameplay/Materials/MI_HitMark_Wood.MI_HitMark_Wood"));
}

UMaterialInterface* ForestItems::GetBuildGhostMaterial()
{
	return LoadObject<UMaterialInterface>(nullptr, TEXT("/Game/Gameplay/Materials/M_BuildGhost.M_BuildGhost"));
}
